import React from 'react';
import { FaTrash, FaShieldAlt, FaEnvelope, FaBell } from 'react-icons/fa';
import { useTheme } from '../../context/ThemeContext';
import styles from './NotificationItem.module.css';

const NotificationItem = ({ notification, onDelete }) => {
    const { theme } = useTheme();

    const formatDate = (dateStr) => {
        if (!dateStr) return '';
        const date = new Date(dateStr);

        // Получаем смещение часового пояса (Минск UTC+3)
        const timezoneOffset = 3 * 60 * 60 * 1000; // 3 часа в миллисекундах

        // Добавляем смещение к UTC времени
        const localDate = new Date(date.getTime() + timezoneOffset);

        return localDate.toLocaleString('ru-RU', {
            day: 'numeric',
            month: 'numeric',
            hour: '2-digit',
            minute: '2-digit'
        });
    };

    const getNotificationIcon = () => {
        switch (notification.NotificationType) {
            case 'admin':
                return <FaShieldAlt className={styles.adminIcon} />;
            case 'system':
                return <FaBell className={styles.systemIcon} />;
            default:
                return <FaEnvelope className={styles.defaultIcon} />;
        }
    };

    const getNotificationBadge = () => {
        switch (notification.NotificationType) {
            case 'admin':
                return <span className={styles.adminBadge}>От администратора</span>;
            case 'system':
                return <span className={styles.systemBadge}>Системное</span>;
            default:
                return null;
        }
    };

    const getDisplayText = () => {
        if (notification.NotificationType === 'admin' && notification.Text?.startsWith('[АДМИН]')) {
            return notification.Text.replace('[АДМИН] ', '');
        }
        return notification.Text;
    };

    return (
        <div
            className={`${styles.notificationItem} ${!notification.IsRead ? styles.unread : ''}`}
            data-theme={theme}
        >
            <div className={styles.notificationIcon}>
                {getNotificationIcon()}
            </div>
            <div className={styles.notificationContent}>
                {getNotificationBadge()}
                <p className={styles.notificationText}>{getDisplayText()}</p>
                <span className={styles.notificationDate}>{formatDate(notification.CreatedDate)}</span>
            </div>
            <button
                className={styles.deleteButton}
                onClick={() => onDelete(notification.Id)}
                aria-label="Удалить уведомление"
            >
                <FaTrash />
            </button>
        </div>
    );
};

export default NotificationItem;
